-- ============================================
-- LUMA — Enrichissement Thématique 11 (Festival) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"friend": "ton ami de festival"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Day one is done! But I heard tomorrow might have rain.", "text_fr": "Le premier jour est fini ! Mais j''ai entendu qu''il pourrait pleuvoir demain.", "choices": [{"text": "Let''s plan for it, ponchos and boots tomorrow.", "next": "n2"}, {"text": "Let''s just hope it holds off, I don''t want to overthink it.", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "Good call — it did rain, but we managed! Day two, our friend Alex twisted an ankle in the mud pit near the stage.", "text_fr": "Bien vu — il a plu, mais on a géré ! Jour deux, notre ami Alex s''est tordu la cheville dans la boue près de la scène.", "choices": [{"text": "Let''s help him to the medical tent right away.", "next": "n3"}, {"text": "Let''s see how bad it is first before panicking.", "next": "n3b"}]}, "n2b": {"speaker": "friend", "text": "(it does rain heavily) Well, that backfired — we''re soaked!", "text_fr": "(il pleut effectivement fort) Eh bien, ça s''est retourné contre nous — on est trempés !", "choices": [{"text": "Let''s laugh it off and buy ponchos from a vendor here.", "next": "n3c"}]}, "n3": {"speaker": "friend", "text": "Good thinking, better safe. The medics say it''s just a sprain.", "text_fr": "Bien pensé, mieux vaut être prudent. Les secouristes disent que c''est juste une entorse.", "choices": [{"text": "Let''s make sure he''s comfortable for the rest of the day.", "next": "n4"}]}, "n3b": {"speaker": "friend", "text": "(it turns out worse than expected, requiring more care) We should''ve gone straight to the medics.", "text_fr": "(ça s''avère pire que prévu, nécessitant plus de soins) On aurait dû aller directement voir les secours.", "choices": [{"text": "Lesson learned — let''s get him proper care now.", "next": "n4"}]}, "n3c": {"speaker": "friend", "text": "Ha, that''s the spirit! Vendor ponchos it is.", "text_fr": "Ha, voilà l''esprit ! Ponchos du vendeur alors.", "choices": [{"text": "Adventure is part of the fun, right?", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "Day three now, the final day. Any regrets so far?", "text_fr": "Jour trois maintenant, le dernier jour. Des regrets jusqu''ici ?", "choices": [{"text": "None, this has been an amazing experience overall.", "next": "n5"}, {"text": "Just that we didn''t plan a bit better for the weather.", "next": "n5b"}]}, "n5": {"speaker": "friend", "text": "Same here. Last big show tonight, let''s make it count!", "text_fr": "Pareil pour moi. Dernier grand concert ce soir, profitons-en à fond !", "choices": [{"text": "Let''s go make some final memories.", "next": "end_finale"}]}, "n5b": {"speaker": "friend", "text": "Fair, but honestly the unexpected moments made it memorable too.", "text_fr": "C''est vrai, mais honnêtement les moments imprévus l''ont aussi rendu mémorable.", "choices": [{"text": "You''re right, let''s finish strong tonight.", "next": "end_finale"}]}, "end_finale": {"speaker": "friend", "text": "Best three days ever, thanks for being here with me.", "text_fr": "Meilleurs trois jours de ma vie, merci d''avoir été là avec moi.", "end": true, "ending_label": "Festival mémorable achevé malgré les imprévus 🎉"}}}'::jsonb, is_playable = true
where title = 'Un festival sur plusieurs jours avec des rebondissements'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"coordinator": "le coordinateur bénévole"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coordinator", "text": "Welcome aboard! You''ll be helping manage crowd flow near the main gate.", "text_fr": "Bienvenue à bord ! Tu vas aider à gérer le flux de foule près de l''entrée principale.", "choices": [{"text": "Sounds great, what should I do if it gets too crowded?", "next": "n2"}, {"text": "Is there additional training before I start?", "next": "n2b"}]}, "n2": {"speaker": "coordinator", "text": "Radio me immediately, we have a backup plan ready.", "text_fr": "Contacte-moi immédiatement par radio, on a un plan de secours prêt.", "choices": [{"text": "Got it, I''ll stay alert.", "next": "n3"}]}, "n2b": {"speaker": "coordinator", "text": "Just a quick briefing — here''s the radio protocol and emergency exits map.", "text_fr": "Juste un briefing rapide — voici le protocole radio et le plan des sorties d''urgence.", "choices": [{"text": "Thanks, this helps me feel prepared.", "next": "n3"}]}, "n3": {"speaker": "coordinator", "text": "(later, a real crowd surge happens) We''ve got a problem — too many people at once!", "text_fr": "(plus tard, une vraie ruée de foule se produit) On a un problème — trop de monde d''un coup !", "choices": [{"text": "I''ll redirect people calmly to the side entrance.", "next": "n4"}, {"text": "Let''s close the gate temporarily until it clears.", "next": "n4b"}]}, "n4": {"speaker": "coordinator", "text": "Great job managing that calmly! The flow is much better now.", "text_fr": "Bravo d''avoir géré ça calmement ! Le flux est bien meilleur maintenant.", "choices": [{"text": "Thank you, the training really helped.", "next": "n5"}]}, "n4b": {"speaker": "coordinator", "text": "Smart call, that gave us time to reorganize safely.", "text_fr": "Bonne décision, ça nous a donné le temps de nous réorganiser en sécurité.", "choices": [{"text": "Safety first, glad it worked out.", "next": "n5"}]}, "n5": {"speaker": "coordinator", "text": "One more challenge — a lost child was found near your station. Can you help reunite them with their parents?", "text_fr": "Un dernier défi — un enfant perdu a été retrouvé près de ton poste. Tu peux aider à le retrouver avec ses parents ?", "choices": [{"text": "Of course, I''ll comfort them and call it in over the radio.", "next": "end_success"}]}, "end_success": {"speaker": "coordinator", "text": "You''ve got real leadership potential, thanks for stepping up all day.", "text_fr": "Tu as un vrai potentiel de leader, merci de t''être investi toute la journée.", "end": true, "ending_label": "Bénévolat exemplaire du début à la fin 🌟"}}}'::jsonb, is_playable = true
where title = 'Bénévolat sur l''événement avec responsabilités'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"stranger": "une personne à proximité", "medic": "un secouriste"}, "start_node": "n1", "nodes": {"n1": {"speaker": "stranger", "text": "Help, my friend just fainted from the heat!", "text_fr": "À l''aide, mon ami vient de s''évanouir à cause de la chaleur !", "choices": [{"text": "Let''s get security and some water immediately.", "next": "n2"}, {"text": "I know first aid, let me check on him first.", "next": "n2b"}]}, "n2": {"speaker": "stranger", "text": "Thank you, I''m panicking a bit.", "text_fr": "Merci, je panique un peu.", "choices": [{"text": "Stay calm, help is on the way, let''s get him some shade.", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "Please, yes, I don''t know what to do.", "text_fr": "S''il te plaît, oui, je ne sais pas quoi faire.", "choices": [{"text": "(check his breathing and pulse while calling for help)", "next": "n3"}]}, "n3": {"speaker": "medic", "text": "(arrives) What happened exactly?", "text_fr": "(arrive) Que s''est-il passé exactement ?", "choices": [{"text": "He collapsed suddenly, seemed dehydrated and overheated.", "next": "n4"}, {"text": "He mentioned feeling dizzy just before it happened.", "next": "n4b"}]}, "n4": {"speaker": "medic", "text": "Classic heat exhaustion. Let''s cool him down and get fluids in him.", "text_fr": "Épuisement dû à la chaleur classique. Refroidissons-le et donnons-lui des liquides.", "choices": [{"text": "I''ll help however I can.", "next": "n5"}]}, "n4b": {"speaker": "medic", "text": "That confirms it — likely dehydration combined with heat. Good detail to know.", "text_fr": "Ça confirme — probablement une déshydratation combinée à la chaleur. Bon détail à savoir.", "choices": [{"text": "Glad that helped, what else can I do?", "next": "n5"}]}, "n5": {"speaker": "medic", "text": "(after treatment) He''s going to be okay, just needed rest and fluids.", "text_fr": "(après traitement) Il va bien, il avait juste besoin de repos et de liquides.", "choices": [{"text": "I''m so relieved, glad we acted fast.", "next": "end_helped"}]}, "end_helped": {"speaker": "stranger", "text": "Thank you for staying calm and helping us through this.", "text_fr": "Merci d''être resté calme et de nous avoir aidés à traverser ça.", "end": true, "ending_label": "Situation d''urgence bien gérée en équipe 🙏"}}}'::jsonb, is_playable = true
where title = 'Un incident à gérer en tant que spectateur impliqué'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
